import CryptoKit
import Foundation
@testable import MSAAAssuranceCore

private enum SelfTestFailure:Error { case failed(String) }
private func expect(_ condition:@autoclosure () throws -> Bool,_ message:String="expectation failed")throws { if try !condition(){throw SelfTestFailure.failed(message)} }
private func expectThrows(_ operation:() throws -> Any)throws { do {_ = try operation();throw SelfTestFailure.failed("expected an error")}catch is SelfTestFailure{throw SelfTestFailure.failed("expected an error")}catch{} }

@main struct AssuranceTests {
