    func passRequiresAllFreshProductionDimensionsAndHealthyCollector()throws {let c=InitialProfile.controls(now:now)[0];let health=CollectorHealth(collectorID:c.requiredCollectorIDs[0],version:"1",capabilities:[],lastStartedAt:now,lastSuccessfulObservationAt:now,lastHeartbeatAt:now,currentState:.healthy,errorReasonCode:nil,droppedEventCount:0,sequenceGapCount:0,permissionState:"notRequired",simulationStatus:.production);var records:[EvidenceObservation]=[];for (i,d) in Dimension.allCases.enumerated(){var value=draft(UInt64(i+1),records.last?.recordDigest ?? Canonical.zeroDigest);value = EvidenceObservation(evidenceID:value.evidenceID,sequenceNumber:value.sequenceNumber,controlID:c.controlID,dimension:d,evidenceType:value.evidenceType,sourceCollectorID:health.collectorID,sourceCollectorVersion:"1",observedAt:now,recordedAt:now,expiresAt:now.addingTimeInterval(300),result:.pass,reasonCode:.requirementSatisfied,humanReadableSummary:"fresh",rawEvidenceDigest:value.rawEvidenceDigest,previousRecordDigest:value.previousRecordDigest,policyVersion:"1",applicationVersion:"1",hostIdentifier:"p",simulationStatus:.production,privacyClassification:"system-metadata");records.append(try EvidenceChain.append(value,to:records))};try expect(Evaluator.evaluate(c,evidence:records,collectors:[health],now:now).overallState == .pass);let expired=CollectorHealth(collectorID:health.collectorID,version:"1",capabilities:[],lastStartedAt:now,lastSuccessfulObservationAt:now,lastHeartbeatAt:now.addingTimeInterval(-7200),currentState:.healthy,errorReasonCode:nil,droppedEventCount:0,sequenceGapCount:0,permissionState:"notRequired",simulationStatus:.production);try expect(Evaluator.evaluate(c,evidence:records,collectors:[expired],now:now).overallState == .degraded)}
    func recoveryFixture()throws{let root=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString);defer{try? FileManager.default.removeItem(at:root)};try expect(try ValidationHarness.recoveryFixture(in:root).result == .pass)}
    func policyRejectsUnsupportedUnknownAndUnsignedProduction()throws{let c=InitialProfile.controls(now:now);let profile=PolicyProfile(schemaVersion:"1.0",profileID:"dev",profileVersion:"1",controls:c,signature:nil);let data=try Canonical.data(profile);_ = try PolicyImporter.load(data,developmentMode:true);try expectThrows {try PolicyImporter.load(data,developmentMode:false)};let unknown=try JSONSerialization.data(withJSONObject:["schemaVersion":"1.0","profileID":"x","profileVersion":"1","controls":[],"unexpected":true]);try expectThrows {try PolicyImporter.load(unknown,developmentMode:true)};let unsupported=try JSONSerialization.data(withJSONObject:["schemaVersion":"2.0","profileID":"x","profileVersion":"1","controls":[]]);try expectThrows {try PolicyImporter.load(unsupported,developmentMode:true)}}
